window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7319a2f980c8873a"]={"versions": [{"id": "FIG-7319a2f980c8873a", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR Basic Software Module Description Templates / BSWMD, Release R3.0.7).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Definition der Klasse <code>BswImplementation</code> als Bindeglied zwischen Software-Code-Artefakten, Modulverhalten (<code>BswBehavior</code>), Hardware-Abhängigkeiten (<code>HWElement</code>) und der ECU-Konfiguration (Parameterdefinitionen <code>ModuleDef</code> sowie Vorkonfigurationen <code>ModuleConfiguration</code>). Es kapselt alle statischen Metadaten zur konkreten Implementierung eines BSW-Moduls für Code-Generatoren und Integrationswerkzeuge.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten und Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>Implementation::Implementation</code></strong> <em>(Stereotyp: <code>«ARElement»</code>)</em>:\n Abstrakte Basisklasse aller Implementierungsbeschreibungen.\n<ul class=\"fig-list\"><li><code>codeGenerator: String [0..1]</code> – Spezifikation des erforderlichen Codegenerator-Tools.\n</li><li><code>programmingLanguage: ProgramminglanguageEnum</code> – Verwendete Sprache (i. d. R. C).\n</li><li><code>swMajorVersion: Int</code>, <code>swMinorVersion: Int</code>, <code>swPatchVersion: Int</code> – Modul-Release-Version des Zulieferers.\n</li><li><code>vendorId: Int</code> – Eindeutige Vendor-ID nach AUTOSAR-Nummernkreis (HIS/AUTOSAR).\n</li></ul>\n</li><li><strong><code>BswImplementation</code></strong> <em>(Stereotyp: <code>«ARElement»</code>, spezialisiert <code>Implementation</code>)</em>:\n Spezifische Implementierungsmetadaten eines BSW-Moduls / BSW-Treibers.\n<ul class=\"fig-list\"><li><code>arMajorVersion: Int</code>, <code>arMinorVersion: Int</code>, <code>arPatchVersion: Int</code> – AUTOSAR-Spezifikationsstand, gegen den das Modul entwickelt wurde.\n</li><li><code>vendorApiInfix: String</code> – Infix zur Unterscheidung multipler Treiber-/Modulinstanzen oder herstellerspezifischer Namensräume (API-Name-Mangling).\n</li></ul>\n</li><li><strong><code>BswBehavior::BswBehavior</code></strong> <em>(Stereotyp: <code>«ARElement»</code>)</em>:\n Verhaltensbeschreibung des BSW-Moduls (Scheduling, MainFunctions, Exklusive Bereiche/Locks, API-Aufrufe).\n</li><li><strong><code>ECUResourceTemplate::HWElement</code></strong> <em>(Stereotyp: <code>«ARElement»</code>)</em>:\n Hardware-Ressourcen des Ziel-Mikrocontrollers/ASICs (z. B. Timer-Channels, Register-Blöcke, CAN-Controller).\n</li><li><strong><code>ECUCParameterDefTemplate::ModuleDef</code></strong> <em>(Stereotypen: <code>«ARElement»</code>, <code>«ParamConfMultiplicity»</code>)</em>:\n Strukturelle Parameterdefinition (Metamodell der konfigurierbaren Parameter des Moduls).\n<ul class=\"fig-list\"><li>Reflexive Assoziation <code>+refinedModuleDef [0..1]</code>: Ermöglicht herstellerspezifische Erweiterung oder Verfeinerung einer standardisierten AUTOSAR-Parameterdefinition.\n</li></ul>\n</li><li><strong><code>ECUCDescriptionTemplate::ModuleConfiguration</code></strong> <em>(Stereotyp: <code>«ARElement»</code>)</em>:\n Instanziierte Konfigurationswerte für das Modul.\n<ul class=\"fig-list\"><li><code>implementationConfigVariant: ConfigurationVariant</code> – Konfigurationsklasse (z. B. <code>VariantPreCompile</code>, <code>VariantLinkTime</code>, <code>VariantPostBuild</code>).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Vererbung:</strong> <code>BswImplementation</code> erbt via Generalisierung von <code>Implementation::Implementation</code>.\n</li><li><strong><code>+behavior</code> [1]:</strong> Unidirektionale 1:1-Assoziation zu <code>BswBehavior</code>; jede BSW-Implementierung muss exakt ein Verhaltensmodell referenzieren.\n</li><li>**<code>+requiredHW</code> [0..\\*]:** Unidirektionale 1:n-Assoziation zu <code>HWElement</code>; deklariert physische Peripherie- oder Controllerelemente, die das Modul zwingend voraussetzt.\n</li><li><strong><code>+vendorSpecificModuleDef</code> [1]:</strong> Unidirektionale Referenz auf das modulspezifische Konfigurationsschema (<code>ModuleDef</code>), das durch den Modullieferanten ausgeliefert wird.\n</li><li><strong><code>+preconfiguredConfiguration</code> [0..1]:</strong> Unidirektionale Referenz auf feste, unveränderliche Parameterbelegungen, die vom Modulentwickler vorgegeben werden.\n</li><li><strong><code>+recommendedConfiguration</code> [0..1]:</strong> Unidirektionale Referenz auf empfohlene Default-Parameterwerte für den Integrator.\n</li><li><strong><code>+definition</code> [1]:</strong> <code>ModuleConfiguration</code> referenziert zwingend genau eine <code>ModuleDef</code> als Schemabasis.\n</li><li><strong><code>+moduleDescription</code> [0..1]:</strong> Unidirektionale Rückwärtsreferenz von <code>ModuleConfiguration</code> auf die zugehörige <code>BswImplementation</code>.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend:</strong> Statisches Metamodell/Klassendiagramm ohne dynamische Zustände oder Laufzeit-Interaktionspfade. Die dynamische Ausführung (Events, Tasks, Main-Functions) wird separat innerhalb des aggregierten <code>BswBehavior</code> modelliert.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Versions- &amp; Kompatibilitätsvalidierung:</strong> Integrationswerkzeuge (BSW-Generatoren/Tresos/DaVinci) validieren über <code>ar*Version</code> und <code>sw*Version</code>, ob BSW-Treiber, Toolchain und RTE-Generator binär- und API-kompatibel sind (z. B. Matching von Vendor-IDs und Release-Ständen).\n</li><li><strong>API-Namenskonvention (<code>vendorApiInfix</code>):</strong> Bei Vorhandensein eines <code>vendorApiInfix</code> müssen Funktionssignaturen und Dateinamen gemäß AUTOSAR-Regularien angepasst werden (z. B. <code>&lt;Module&gt;_&lt;VendorId&gt;_&lt;VendorApiInfix&gt;_&lt;ApiName&gt;</code>), relevant für Multi-Vendor-Stacks oder mehrkanalige Hardware-Treiber desselben Modultyps.\n</li><li><strong>Konfigurationsworkflow:</strong>\n<ul class=\"fig-list\"><li><code>preconfiguredConfiguration</code> sperrt bestimmte Parameter im Konfigurator gegen Überschreiben durch den OEM/Tier-1.\n</li><li><code>recommendedConfiguration</code> liefert die Basis-Initialisierungswerte beim Import der BSWMD in die Projektkonfiguration.\n</li></ul>\n</li><li><strong>Hardware-Zuordnung:</strong> Fehlt eine Zuordnung in <code>requiredHW</code> oder existiert der referenzierte <code>HWElement</code>-Knoten im ECU-Ressourcendeskriptor der Ziel-Hardware nicht, blockiert der Konfigurationsgenerator die Validierungsphase vor der Code-Generierung.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4fd69934c175b598", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR Basic Software Module Description Templates / BSWMD, Release R3.0.7).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Definition der Klasse <code>BswImplementation</code> als Bindeglied zwischen Software-Code-Artefakten, Modulverhalten (<code>BswBehavior</code>), Hardware-Abhängigkeiten (<code>HWElement</code>) und der ECU-Konfiguration (Parameterdefinitionen <code>ModuleDef</code> sowie Vorkonfigurationen <code>ModuleConfiguration</code>). Es kapselt alle statischen Metadaten zur konkreten Implementierung eines BSW-Moduls für Code-Generatoren und Integrationswerkzeuge.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten und Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>Implementation::Implementation</code></strong> <em>(Stereotyp: <code>«ARElement»</code>)</em>:\n Abstrakte Basisklasse aller Implementierungsbeschreibungen.\n<ul class=\"fig-list\"><li><code>codeGenerator: String [0..1]</code> – Spezifikation des erforderlichen Codegenerator-Tools.\n</li><li><code>programmingLanguage: ProgramminglanguageEnum</code> – Verwendete Sprache (i. d. R. C).\n</li><li><code>swMajorVersion: Int</code>, <code>swMinorVersion: Int</code>, <code>swPatchVersion: Int</code> – Modul-Release-Version des Zulieferers.\n</li><li><code>vendorId: Int</code> – Eindeutige Vendor-ID nach AUTOSAR-Nummernkreis (HIS/AUTOSAR).\n</li></ul>\n</li><li><strong><code>BswImplementation</code></strong> <em>(Stereotyp: <code>«ARElement»</code>, spezialisiert <code>Implementation</code>)</em>:\n Spezifische Implementierungsmetadaten eines BSW-Moduls / BSW-Treibers.\n<ul class=\"fig-list\"><li><code>arMajorVersion: Int</code>, <code>arMinorVersion: Int</code>, <code>arPatchVersion: Int</code> – AUTOSAR-Spezifikationsstand, gegen den das Modul entwickelt wurde.\n</li><li><code>vendorApiInfix: String</code> – Infix zur Unterscheidung multipler Treiber-/Modulinstanzen oder herstellerspezifischer Namensräume (API-Name-Mangling).\n</li></ul>\n</li><li><strong><code>BswBehavior::BswBehavior</code></strong> <em>(Stereotyp: <code>«ARElement»</code>)</em>:\n Verhaltensbeschreibung des BSW-Moduls (Scheduling, MainFunctions, Exklusive Bereiche/Locks, API-Aufrufe).\n</li><li><strong><code>ECUResourceTemplate::HWElement</code></strong> <em>(Stereotyp: <code>«ARElement»</code>)</em>:\n Hardware-Ressourcen des Ziel-Mikrocontrollers/ASICs (z. B. Timer-Channels, Register-Blöcke, CAN-Controller).\n</li><li><strong><code>ECUCParameterDefTemplate::ModuleDef</code></strong> <em>(Stereotypen: <code>«ARElement»</code>, <code>«ParamConfMultiplicity»</code>)</em>:\n Strukturelle Parameterdefinition (Metamodell der konfigurierbaren Parameter des Moduls).\n<ul class=\"fig-list\"><li>Reflexive Assoziation <code>+refinedModuleDef [0..1]</code>: Ermöglicht herstellerspezifische Erweiterung oder Verfeinerung einer standardisierten AUTOSAR-Parameterdefinition.\n</li></ul>\n</li><li><strong><code>ECUCDescriptionTemplate::ModuleConfiguration</code></strong> <em>(Stereotyp: <code>«ARElement»</code>)</em>:\n Instanziierte Konfigurationswerte für das Modul.\n<ul class=\"fig-list\"><li><code>implementationConfigVariant: ConfigurationVariant</code> – Konfigurationsklasse (z. B. <code>VariantPreCompile</code>, <code>VariantLinkTime</code>, <code>VariantPostBuild</code>).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Vererbung:</strong> <code>BswImplementation</code> erbt via Generalisierung von <code>Implementation::Implementation</code>.\n</li><li><strong><code>+behavior</code> [1]:</strong> Unidirektionale 1:1-Assoziation zu <code>BswBehavior</code>; jede BSW-Implementierung muss exakt ein Verhaltensmodell referenzieren.\n</li><li>**<code>+requiredHW</code> [0..\\*]:** Unidirektionale 1:n-Assoziation zu <code>HWElement</code>; deklariert physische Peripherie- oder Controllerelemente, die das Modul zwingend voraussetzt.\n</li><li><strong><code>+vendorSpecificModuleDef</code> [1]:</strong> Unidirektionale Referenz auf das modulspezifische Konfigurationsschema (<code>ModuleDef</code>), das durch den Modullieferanten ausgeliefert wird.\n</li><li><strong><code>+preconfiguredConfiguration</code> [0..1]:</strong> Unidirektionale Referenz auf feste, unveränderliche Parameterbelegungen, die vom Modulentwickler vorgegeben werden.\n</li><li><strong><code>+recommendedConfiguration</code> [0..1]:</strong> Unidirektionale Referenz auf empfohlene Default-Parameterwerte für den Integrator.\n</li><li><strong><code>+definition</code> [1]:</strong> <code>ModuleConfiguration</code> referenziert zwingend genau eine <code>ModuleDef</code> als Schemabasis.\n</li><li><strong><code>+moduleDescription</code> [0..1]:</strong> Unidirektionale Rückwärtsreferenz von <code>ModuleConfiguration</code> auf die zugehörige <code>BswImplementation</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend:</strong> Statisches Metamodell/Klassendiagramm ohne dynamische Zustände oder Laufzeit-Interaktionspfade. Die dynamische Ausführung (Events, Tasks, Main-Functions) wird separat innerhalb des aggregierten <code>BswBehavior</code> modelliert.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Versions- &amp; Kompatibilitätsvalidierung:</strong> Integrationswerkzeuge (BSW-Generatoren/Tresos/DaVinci) validieren über <code>ar*Version</code> und <code>sw*Version</code>, ob BSW-Treiber, Toolchain und RTE-Generator binär- und API-kompatibel sind (z. B. Matching von Vendor-IDs und Release-Ständen).\n</li><li><strong>API-Namenskonvention (<code>vendorApiInfix</code>):</strong> Bei Vorhandensein eines <code>vendorApiInfix</code> müssen Funktionssignaturen und Dateinamen gemäß AUTOSAR-Regularien angepasst werden (z. B. <code>&lt;Module&gt;_&lt;VendorId&gt;_&lt;VendorApiInfix&gt;_&lt;ApiName&gt;</code>), relevant für Multi-Vendor-Stacks oder mehrkanalige Hardware-Treiber desselben Modultyps.\n</li><li><strong>Konfigurationsworkflow:</strong>\n<ul class=\"fig-list\"><li><code>preconfiguredConfiguration</code> sperrt bestimmte Parameter im Konfigurator gegen Überschreiben durch den OEM/Tier-1.\n</li><li><code>recommendedConfiguration</code> liefert die Basis-Initialisierungswerte beim Import der BSWMD in die Projektkonfiguration.\n</li></ul>\n</li><li><strong>Hardware-Zuordnung:</strong> Fehlt eine Zuordnung in <code>requiredHW</code> oder existiert der referenzierte <code>HWElement</code>-Knoten im ECU-Ressourcendeskriptor der Ziel-Hardware nicht, blockiert der Konfigurationsgenerator die Validierungsphase vor der Code-Generierung.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5fa2b934110d9ab6", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR Basic Software Module Description Templates / BSWMD, Release R3.0.7).\n</li><li><strong>Technischer Zweck &amp; Einordnung:</strong> Definition der Klasse <code>BswImplementation</code> als Bindeglied zwischen Software-Code-Artefakten, Modulverhalten (<code>BswBehavior</code>), Hardware-Abhängigkeiten (<code>HWElement</code>) und der ECU-Konfiguration (Parameterdefinitionen <code>ModuleDef</code> sowie Vorkonfigurationen <code>ModuleConfiguration</code>). Es kapselt alle statischen Metadaten zur konkreten Implementierung eines BSW-Moduls für Code-Generatoren und Integrationswerkzeuge.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten und Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>Implementation::Implementation</code></strong> <em>(Stereotyp: <code>«ARElement»</code>)</em>:\n Abstrakte Basisklasse aller Implementierungsbeschreibungen.\n<ul class=\"fig-list\"><li><code>codeGenerator :String [0..1]</code> – Spezifikation des erforderlichen Codegenerator-Tools.\n</li><li><code>programmingLanguage :ProgramminglanguageEnum</code> – Verwendete Programmiersprache (i. d. R. C).\n</li><li><code>swMajorVersion :Integer</code>, <code>swMinorVersion :Integer</code>, <code>swPatchVersion :Integer</code> – Modul-Release-Version des Software-Lieferanten.\n</li><li><code>vendorId :Integer</code> – Eindeutige Vendor-ID nach AUTOSAR-Nummernkreis (HIS/AUTOSAR).\n</li></ul>\n</li><li><strong><code>BswImplementation</code></strong> <em>(Stereotyp: <code>«ARElement»</code>, spezialisiert <code>Implementation</code>)</em>:\n Spezifische Implementierungsmetadaten eines BSW-Moduls / BSW-Treibers.\n<ul class=\"fig-list\"><li><code>arMajorVersion :Integer</code>, <code>arMinorVersion :Integer</code>, <code>arPatchVersion :Integer</code> – AUTOSAR-Spezifikationsstand, gegen den das Modul entwickelt wurde.\n</li><li><code>vendorApiInfix :String</code> – Infix zur Unterscheidung multipler Treiber-/Modulinstanzen oder herstellerspezifischer Namensräume (API-Name-Mangling).\n</li></ul>\n</li><li><strong><code>BswBehavior::BswBehavior</code></strong> <em>(Stereotyp: <code>«ARElement»</code>)</em>:\n Verhaltensbeschreibung des BSW-Moduls (Scheduling, MainFunctions, Exklusive Bereiche/Locks, API-Aufrufe).\n</li><li><strong><code>ECUResourceTemplate::HWElement</code></strong> <em>(Stereotyp: <code>«ARElement»</code>)</em>:\n Hardware-Ressourcen des Ziel-Mikrocontrollers/ASICs (z. B. Timer-Channels, Register-Blöcke, CAN-Controller).\n</li><li><strong><code>ECUCParameterDefTemplate::ModuleDef</code></strong> <em>(Stereotypen: <code>«ARElement»</code>, <code>«ParamConfMultiplicity»</code>)</em>:\n Strukturelle Parameterdefinition (Metamodell der konfigurierbaren Parameter des Moduls).\n<ul class=\"fig-list\"><li>Reflexive Assoziation <code>+refinedModuleDef [0..1]</code>: Ermöglicht herstellerspezifische Erweiterung oder Verfeinerung einer standardisierten AUTOSAR-Parameterdefinition.\n</li></ul>\n</li><li><strong><code>ECUCDescriptionTemplate::ModuleConfiguration</code></strong> <em>(Stereotyp: <code>«ARElement»</code>)</em>:\n Instanziierte Konfigurationswerte für das Modul.\n<ul class=\"fig-list\"><li><code>implementationConfigVariant :ConfigurationVariant</code> – Konfigurationsklasse (z. B. <code>VariantPreCompile</code>, <code>VariantLinkTime</code>, <code>VariantPostBuild</code>).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong>Vererbung:</strong> <code>BswImplementation</code> erbt via Generalisierung von <code>Implementation::Implementation</code>.\n</li><li><strong><code>+behavior</code> [1]:</strong> Unidirektionale 1:1-Assoziation zu <code>BswBehavior</code>; jede BSW-Implementierung muss exakt ein Verhaltensmodell referenzieren.\n</li><li>**<code>+requiredHW</code> [0..*]:** Unidirektionale 1:n-Assoziation zu <code>HWElement</code>; deklariert physische Peripherie- oder Controllerelemente, die das Modul zwingend voraussetzt.\n</li><li><strong><code>+vendorSpecificModuleDef</code> [1]:</strong> Unidirektionale Referenz auf das modulspezifische Konfigurationsschema (<code>ModuleDef</code>), das durch den Modullieferanten ausgeliefert wird.\n</li><li><strong><code>+preconfiguredConfiguration</code> [0..1]:</strong> Unidirektionale Referenz auf feste, unveränderliche Parameterbelegungen, die vom Modulentwickler vorgegeben werden.\n</li><li><strong><code>+recommendedConfiguration</code> [0..1]:</strong> Unidirektionale Referenz auf empfohlene Konfigurationswerte (Default-Werte / Richtwerte für Integratoren).\n</li><li><strong><code>+moduleDescription</code> [0..1]:</strong> Unidirektionale Rückreferenz von <code>ModuleConfiguration</code> auf die Metaklasse <code>BswImplementation</code>.\n</li><li><strong><code>+definition</code> [1]:</strong> Unidirektionale Referenz von <code>ModuleConfiguration</code> auf das zugehörige Parameterschema <code>ModuleDef</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend:</strong> Statisches Metamodell/Klassendiagramm ohne dynamische Zustände oder Laufzeit-Interaktionspfade. Die dynamische Ausführung (Events, Tasks, Main-Functions) wird separat innerhalb des aggregierten <code>BswBehavior</code> modelliert.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Versions- &amp; Kompatibilitätsvalidierung:</strong> Integrationswerkzeuge (BSW-Generatoren/Tresos/DaVinci) validieren über <code>ar*Version</code> und <code>sw*Version</code>, ob BSW-Treiber, Toolchain und RTE-Generator binär- und API-kompatibel sind (z. B. Matching von Vendor-IDs und Release-Ständen).\n</li><li><strong>API-Namenskonvention (<code>vendorApiInfix</code>):</strong> Bei Vorhandensein eines <code>vendorApiInfix</code> müssen Funktionssignaturen und Dateinamen gemäß AUTOSAR-Regularien angepasst werden (z. B. <code>&lt;Module&gt;_&lt;VendorId&gt;_&lt;VendorApiInfix&gt;_&lt;ApiName&gt;</code>), relevant für Multi-Vendor-Stacks oder mehrkanalige Hardware-Treiber desselben Modultyps.\n</li><li><strong>Konfigurationsworkflow:</strong>\n<ul class=\"fig-list\"><li><code>preconfiguredConfiguration</code> sperrt bestimmte Parameter im Konfigurator gegen Überschreiben durch den OEM/Tier-1.\n</li><li><code>recommendedConfiguration</code> liefert die Basis-Initialisierungswerte beim Import der BSWMD in die Projektkonfiguration.\n</li></ul>\n</li><li><strong>Hardware-Zuordnung:</strong> Fehlt eine Zuordnung in <code>requiredHW</code> oder existiert der referenzierte <code>HWElement</code>-Knoten im ECU-Ressourcendeskriptor der Ziel-Hardware nicht, blockiert der Konfigurationsgenerator die Validierungsphase vor der Code-Generierung.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-7319a2f980c8873a", "to": "FIG-4fd69934c175b598", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4fd69934c175b598", "to": "FIG-5fa2b934110d9ab6", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>Implementation::Implementation</code>: Datentyp der Attribute <code>swMajorVersion</code>, <code>swMinorVersion</code>, <code>swPatchVersion</code> und <code>vendorId</code> von <code>Int</code> zu <code>Integer</code> geändert.\n</li><li><code>BswImplementation</code>: Datentyp der Attribute <code>arMajorVersion</code>, <code>arMinorVersion</code> und <code>arPatchVersion</code> von <code>Int</code> zu <code>Integer</code> geändert.\n</li><li>Notation: Typdeklarationen der Attribute typografisch mit Leerzeichen vor dem Doppelpunkt formatiert (<code> :Integer</code>, <code> :String</code>, <code> :ProgramminglanguageEnum</code>, <code> :ConfigurationVariant</code>).\n</li></ul>"}]};
